package com.meterflow.subscriptions;import jakarta.persistence.*;import java.math.*;import java.time.*;import java.util.*;
@Entity @Table(name="subscription_plan_changes") public class PlanChange{@Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@Column(nullable=false)private UUID subscriptionId;@Column(nullable=false)private UUID fromPlanId;@Column(nullable=false)private UUID toPlanId;@Column(nullable=false,precision=18,scale=2)private BigDecimal proratedDelta;@Column(nullable=false)private String currency;@Column(nullable=false)private LocalDate effectiveDate;protected PlanChange(){}public PlanChange(UUID s,UUID f,UUID t,BigDecimal d,String c,LocalDate date){subscriptionId=s;fromPlanId=f;toPlanId=t;proratedDelta=d;currency=c;effectiveDate=date;}public UUID getId(){return id;}public UUID getSubscriptionId(){return subscriptionId;}public UUID getFromPlanId(){return fromPlanId;}public UUID getToPlanId(){return toPlanId;}public BigDecimal getProratedDelta(){return proratedDelta;}public String getCurrency(){return currency;}public LocalDate getEffectiveDate(){return effectiveDate;}}
